'use strict';

const fs = require('fs');
const yaml = require('js-yaml');

/**
 * Resolve a local_path value, expanding env: references.
 * Returns null if the value is empty or the referenced env var is unset.
 * @param {string|null|undefined} localPath
 * @returns {string|null}
 */
function resolveLocalPath(localPath) {
  if (!localPath) return null;

  if (localPath.startsWith('env:')) {
    const varName = localPath.slice(4);
    return process.env[varName] || null;
  }

  return localPath;
}

/**
 * Load and validate workspace.yaml.
 * @param {string|null|undefined} filePath - Path to workspace.yaml
 * @returns {object} Parsed config object
 * @throws {Error} If filePath is falsy, file is missing, or repos[] is empty
 */
function loadWorkspaceYaml(filePath) {
  if (!filePath) {
    throw new Error('WORKSPACE_YAML_PATH environment variable is required');
  }

  const content = fs.readFileSync(filePath, 'utf-8');
  const config = yaml.load(content);

  if (!config || !Array.isArray(config.repos) || config.repos.length === 0) {
    throw new Error(`workspace.yaml at ${filePath} has no repos[] entries`);
  }

  return config;
}

/**
 * Extract repo entries from a loaded workspace config.
 * @param {object} config - Parsed workspace.yaml object
 * @returns {{ id: string, sshUrl: string, localPath: string|null }[]}
 */
function getRepoEntries(config) {
  return (config.repos || []).map((repo) => ({
    id: repo.id,
    sshUrl: repo.github || repo.ssh_url || '',
    localPath: resolveLocalPath(repo.local_path || ''),
  }));
}

module.exports = { loadWorkspaceYaml, getRepoEntries, resolveLocalPath };

