'use strict';

const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');
const os = require('os');
const { log } = require('./logger');

/**
 * Write SSH_PRIVATE_KEY to a temp file with mode 0600.
 * Returns the file path, or null if no key is provided.
 * @param {string|null|undefined} rawKey - Raw PEM content (may have literal \n escapes)
 * @returns {string|null}
 */
function setupSshKey(rawKey) {
  if (!rawKey) return null;

  const normalizedKey = rawKey.replace(/\\n/g, '\n');
  const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'gitnexus-ssh-'));
  const keyPath = path.join(tmpDir, 'id_rsa');
  fs.writeFileSync(keyPath, normalizedKey, { mode: 0o600 });
  return keyPath;
}

/**
 * Build a GIT_SSH_COMMAND value that forces use of the given key.
 * @param {string} keyPath
 * @returns {string}
 */
function buildGitSshCommand(keyPath) {
  return `ssh -i ${keyPath} -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null`;
}

/**
 * Return a copy of process.env with GIT_SSH_COMMAND set if a key is provided.
 * @param {string|null} keyPath
 * @returns {object}
 */
function getGitEnv(keyPath) {
  const env = { ...process.env };
  if (keyPath) {
    env.GIT_SSH_COMMAND = buildGitSshCommand(keyPath);
  }
  return env;
}

/**
 * Clone sshUrl into dest. Returns true on success.
 * @param {string} sshUrl
 * @param {string} dest
 * @param {string|null} keyPath
 * @returns {boolean}
 */
function cloneRepo(sshUrl, dest, keyPath) {
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  const env = getGitEnv(keyPath);

  try {
    execSync(`git clone ${sshUrl} ${dest}`, { env, stdio: 'pipe' });
    log('gitnexus_clone_done', { sshUrl, dest });
    return true;
  } catch (err) {
    log('gitnexus_clone_failed', { sshUrl, dest, error: err.message });
    return false;
  }
}

/**
 * Pull latest changes in an already-cloned repo. Returns true on success.
 * Failures are logged as warnings but do not throw.
 * @param {string} repoPath
 * @param {string|null} keyPath
 * @returns {boolean}
 */
function pullRepo(repoPath, keyPath) {
  const env = getGitEnv(keyPath);

  try {
    execSync('git pull --ff-only', { cwd: repoPath, env, stdio: 'pipe' });
    return true;
  } catch (err) {
    log('gitnexus_pull_failed', { repoPath, error: err.message });
    return false;
  }
}

/**
 * Ensure the repo is available locally: pull if already cloned, else clone.
 * Returns the local path, or null if both clone and pull fail.
 * @param {string} repoId
 * @param {string} sshUrl
 * @param {string} reposBase - Base directory for cloned repos
 * @param {string|null} keyPath
 * @returns {string|null}
 */
function ensureRepo(repoId, sshUrl, reposBase, keyPath) {
  const dest = path.join(reposBase, repoId);

  if (fs.existsSync(path.join(dest, '.git'))) {
    pullRepo(dest, keyPath);
    return dest;
  }

  const success = cloneRepo(sshUrl, dest, keyPath);
  return success ? dest : null;
}

module.exports = { setupSshKey, buildGitSshCommand, getGitEnv, cloneRepo, pullRepo, ensureRepo };

