'use strict';

const fs = require('fs');
const { log } = require('./src/logger');
const { loadWorkspaceYaml, getRepoEntries } = require('./src/workspace');
const { setupSshKey, ensureRepo } = require('./src/git');
const { analyzeRepo } = require('./src/analyzer');

const WORKSPACE_YAML_PATH = process.env.WORKSPACE_YAML_PATH;
const SSH_PRIVATE_KEY = process.env.SSH_PRIVATE_KEY || '';
const POLL_INTERVAL_SECONDS = parseInt(process.env.GITNEXUS_POLL_INTERVAL_SECONDS || '300', 10);
const REPOS_BASE = process.env.REPOS_BASE || '/gitnexus-index/repos';
const GITNEXUS_DATA = process.env.HOME || '/gitnexus-data';

/**
 * Run one indexing cycle: resolve repos from workspace.yaml, clone/pull each,
 * then run gitnexus analyze on each.
 * @param {string|null} sshKeyPath
 */
async function runCycle(sshKeyPath) {
  const config = loadWorkspaceYaml(WORKSPACE_YAML_PATH);
  const repos = getRepoEntries(config);

  for (const repo of repos) {
    let repoPath = null;

    if (repo.localPath && fs.existsSync(repo.localPath)) {
      repoPath = repo.localPath;
      log('gitnexus_repo_local', { repoId: repo.id, repoPath });
    } else if (repo.sshUrl) {
      repoPath = ensureRepo(repo.id, repo.sshUrl, REPOS_BASE, sshKeyPath);
    } else {
      log('gitnexus_repo_skip', { repoId: repo.id, reason: 'no_local_path_or_ssh_url' });
      continue;
    }

    if (repoPath) {
      await analyzeRepo(repo.id, repoPath, GITNEXUS_DATA);
    }
  }
}

/**
 * Main entry point. Runs forever, cycling through repos on the configured
 * poll interval until the process is killed.
 */
async function main() {
  log('gitnexus_indexer_start', {
    workspaceYamlPath: WORKSPACE_YAML_PATH,
    pollIntervalSeconds: POLL_INTERVAL_SECONDS,
    gitnexusData: GITNEXUS_DATA,
  });

  const sshKeyPath = setupSshKey(SSH_PRIVATE_KEY);

  while (true) {
    const cycleStart = Date.now();
    log('gitnexus_cycle_start');

    try {
      await runCycle(sshKeyPath);
    } catch (err) {
      log('gitnexus_cycle_error', { error: err.message, stack: err.stack });
    }

    const elapsed = (Date.now() - cycleStart) / 1000;
    const sleepSeconds = Math.max(0, POLL_INTERVAL_SECONDS - elapsed);
    log('gitnexus_cycle_complete', { elapsedSeconds: elapsed, sleepSeconds });

    await new Promise((resolve) => setTimeout(resolve, sleepSeconds * 1000));
  }
}

if (require.main === module) {
  main().catch((err) => {
    log('gitnexus_fatal', { error: err.message });
    process.exit(1);
  });
}

module.exports = { runCycle, main };

