'use strict';

const { log } = require('../src/logger');

describe('log', () => {
  let consoleSpy;

  beforeEach(() => {
    consoleSpy = jest.spyOn(console, 'log').mockImplementation(() => {});
  });

  afterEach(() => {
    consoleSpy.mockRestore();
  });

  it('outputs valid JSON to stdout', () => {
    log('gitnexus_test_event', { key: 'value' });

    expect(consoleSpy).toHaveBeenCalledTimes(1);
    const output = JSON.parse(consoleSpy.mock.calls[0][0]);
    expect(output.event).toBe('gitnexus_test_event');
    expect(output.key).toBe('value');
  });

  it('includes event and timestamp fields', () => {
    log('my_event');

    const output = JSON.parse(consoleSpy.mock.calls[0][0]);
    expect(output.event).toBe('my_event');
    expect(output.timestamp).toBeTruthy();
  });

  it('includes timestamp in ISO 8601 format', () => {
    log('ts_test');

    const output = JSON.parse(consoleSpy.mock.calls[0][0]);
    expect(new Date(output.timestamp).toISOString()).toBe(output.timestamp);
  });

  it('merges extra data fields into the log record', () => {
    log('event_with_data', { repoId: 'my-repo', exitCode: 1 });

    const output = JSON.parse(consoleSpy.mock.calls[0][0]);
    expect(output.repoId).toBe('my-repo');
    expect(output.exitCode).toBe(1);
  });

  it('works with no data argument', () => {
    expect(() => log('bare_event')).not.toThrow();
    const output = JSON.parse(consoleSpy.mock.calls[0][0]);
    expect(output.event).toBe('bare_event');
  });
});

