'use strict';

const fs = require('fs');
const path = require('path');
const { setupSshKey, buildGitSshCommand, getGitEnv } = require('../src/git');

describe('setupSshKey', () => {
  const createdDirs = [];

  afterEach(() => {
    for (const dir of createdDirs.splice(0)) {
      try { fs.rmSync(dir, { recursive: true, force: true }); } catch (_) {}
    }
  });

  it('returns null for empty string', () => {
    expect(setupSshKey('')).toBeNull();
  });

  it('returns null for null', () => {
    expect(setupSshKey(null)).toBeNull();
  });

  it('returns null for undefined', () => {
    expect(setupSshKey(undefined)).toBeNull();
  });

  it('writes key to a temp file', () => {
    const rawKey = '[REDACTED:ssh-private-key]\n';
    const keyPath = setupSshKey(rawKey);
    createdDirs.push(path.dirname(keyPath));

    expect(keyPath).toBeTruthy();
    expect(fs.existsSync(keyPath)).toBe(true);
    expect(fs.readFileSync(keyPath, 'utf-8')).toBe(rawKey);
  });

  it('sets file mode to 0600', () => {
    const rawKey = '[REDACTED:ssh-private-key]\n';
    const keyPath = setupSshKey(rawKey);
    createdDirs.push(path.dirname(keyPath));

    const stat = fs.statSync(keyPath);
    expect(stat.mode & 0o777).toBe(0o600);
  });

  it('normalizes literal \\n escape sequences', () => {
    const rawKey = '[REDACTED:ssh-private-key]\\n';
    const keyPath = setupSshKey(rawKey);
    createdDirs.push(path.dirname(keyPath));

    const content = fs.readFileSync(keyPath, 'utf-8');
    expect(content).toContain('\n');
    expect(content).not.toContain('\\n');
  });
});

describe('buildGitSshCommand', () => {
  it('contains the key path', () => {
    const cmd = buildGitSshCommand('/tmp/id_rsa');
    expect(cmd).toContain('/tmp/id_rsa');
  });

  it('disables strict host key checking', () => {
    const cmd = buildGitSshCommand('/tmp/id_rsa');
    expect(cmd).toContain('-o StrictHostKeyChecking=no');
  });

  it('suppresses known_hosts writes', () => {
    const cmd = buildGitSshCommand('/tmp/id_rsa');
    expect(cmd).toContain('-o UserKnownHostsFile=/dev/null');
  });
});

describe('getGitEnv', () => {
  it('does not set GIT_SSH_COMMAND when keyPath is null', () => {
    const env = getGitEnv(null);
    expect(env.GIT_SSH_COMMAND).toBeUndefined();
  });

  it('sets GIT_SSH_COMMAND when keyPath is provided', () => {
    const env = getGitEnv('/tmp/id_rsa');
    expect(env.GIT_SSH_COMMAND).toBeTruthy();
    expect(env.GIT_SSH_COMMAND).toContain('/tmp/id_rsa');
  });

  it('returns a copy of process.env (does not mutate original)', () => {
    const before = process.env.GIT_SSH_COMMAND;
    getGitEnv('/tmp/id_rsa');
    expect(process.env.GIT_SSH_COMMAND).toBe(before);
  });
});

