'use strict';

jest.mock('child_process', () => ({
  spawn: jest.fn(),
}));

const { spawn } = require('child_process');
const { analyzeRepo } = require('../src/analyzer');

/**
 * Build a minimal fake child process that supports the event API used by analyzeRepo.
 */
function makeFakeProc() {
  const handlers = {};
  const stderrHandlers = {};

  const proc = {
    stdout: { on: jest.fn() },
    stderr: {
      on: jest.fn().mockImplementation((event, cb) => {
        stderrHandlers[event] = cb;
      }),
      _emit: (event, ...args) => {
        if (stderrHandlers[event]) stderrHandlers[event](...args);
      },
    },
    on: jest.fn().mockImplementation((event, cb) => {
      handlers[event] = cb;
    }),
    emit: (event, ...args) => {
      if (handlers[event]) handlers[event](...args);
    },
  };

  return proc;
}

describe('analyzeRepo', () => {
  let consoleSpy;

  beforeEach(() => {
    spawn.mockClear();
    consoleSpy = jest.spyOn(console, 'log').mockImplementation(() => {});
  });

  afterEach(() => {
    consoleSpy.mockRestore();
  });

  it('resolves true on exit code 0', async () => {
    const proc = makeFakeProc();
    spawn.mockReturnValue(proc);

    const promise = analyzeRepo('my-repo', '/path/to/repo');
    proc.emit('close', 0);

    await expect(promise).resolves.toBe(true);
  });

  it('calls spawn with correct npx gitnexus arguments', async () => {
    const proc = makeFakeProc();
    spawn.mockReturnValue(proc);

    const promise = analyzeRepo('my-repo', '/path/to/repo');
    proc.emit('close', 0);
    await promise;

    expect(spawn).toHaveBeenCalledWith(
      'npx',
      ['-y', 'gitnexus@latest', 'analyze', '/path/to/repo'],
      expect.any(Object),
    );
  });

  it('sets HOME env var to gitnexusDataPath', async () => {
    const proc = makeFakeProc();
    spawn.mockReturnValue(proc);

    const promise = analyzeRepo('my-repo', '/path/to/repo', '/custom/data');
    proc.emit('close', 0);
    await promise;

    const spawnOptions = spawn.mock.calls[0][2];
    expect(spawnOptions.env.HOME).toBe('/custom/data');
  });

  it('uses /gitnexus-data as default HOME', async () => {
    const proc = makeFakeProc();
    spawn.mockReturnValue(proc);

    const promise = analyzeRepo('my-repo', '/path/to/repo');
    proc.emit('close', 0);
    await promise;

    const spawnOptions = spawn.mock.calls[0][2];
    expect(spawnOptions.env.HOME).toBe('/gitnexus-data');
  });

  it('resolves false on non-zero exit code', async () => {
    const proc = makeFakeProc();
    spawn.mockReturnValue(proc);

    const promise = analyzeRepo('my-repo', '/path/to/repo');
    proc.emit('close', 1);

    await expect(promise).resolves.toBe(false);
  });

  it('resolves false on spawn error', async () => {
    const proc = makeFakeProc();
    spawn.mockReturnValue(proc);

    const promise = analyzeRepo('my-repo', '/path/to/repo');
    proc.emit('error', new Error('ENOENT'));

    await expect(promise).resolves.toBe(false);
  });

  it('emits gitnexus_analyze_start log event', async () => {
    const proc = makeFakeProc();
    spawn.mockReturnValue(proc);

    const promise = analyzeRepo('repo-x', '/repo/x');
    proc.emit('close', 0);
    await promise;

    const logLines = consoleSpy.mock.calls.map((c) => JSON.parse(c[0]));
    const startEvent = logLines.find((l) => l.event === 'gitnexus_analyze_start');
    expect(startEvent).toBeDefined();
    expect(startEvent.repoId).toBe('repo-x');
  });

  it('emits gitnexus_analyze_done log event on success', async () => {
    const proc = makeFakeProc();
    spawn.mockReturnValue(proc);

    const promise = analyzeRepo('repo-y', '/repo/y');
    proc.emit('close', 0);
    await promise;

    const logLines = consoleSpy.mock.calls.map((c) => JSON.parse(c[0]));
    const doneEvent = logLines.find((l) => l.event === 'gitnexus_analyze_done');
    expect(doneEvent).toBeDefined();
    expect(doneEvent.repoId).toBe('repo-y');
  });

  it('emits gitnexus_analyze_failed log event on failure', async () => {
    const proc = makeFakeProc();
    spawn.mockReturnValue(proc);

    const promise = analyzeRepo('repo-z', '/repo/z');
    proc.emit('close', 2);
    await promise;

    const logLines = consoleSpy.mock.calls.map((c) => JSON.parse(c[0]));
    const failEvent = logLines.find((l) => l.event === 'gitnexus_analyze_failed');
    expect(failEvent).toBeDefined();
    expect(failEvent.exitCode).toBe(2);
  });

  it('emits gitnexus_analyze_failed log event on spawn error', async () => {
    const proc = makeFakeProc();
    spawn.mockReturnValue(proc);

    const promise = analyzeRepo('repo-err', '/repo/err');
    proc.emit('error', new Error('spawn ENOENT'));
    await promise;

    const logLines = consoleSpy.mock.calls.map((c) => JSON.parse(c[0]));
    const failEvent = logLines.find((l) => l.event === 'gitnexus_analyze_failed');
    expect(failEvent).toBeDefined();
    expect(failEvent.error).toContain('ENOENT');
  });
});

