'use strict';

jest.mock('../src/workspace');
jest.mock('../src/git');
jest.mock('../src/analyzer');

const { loadWorkspaceYaml, getRepoEntries } = require('../src/workspace');
const { setupSshKey, ensureRepo } = require('../src/git');
const { analyzeRepo } = require('../src/analyzer');
const { runCycle } = require('../index');

const fs = require('fs');
jest.mock('fs', () => ({
  ...jest.requireActual('fs'),
  existsSync: jest.fn(),
}));

describe('runCycle', () => {
  let consoleSpy;

  beforeEach(() => {
    consoleSpy = jest.spyOn(console, 'log').mockImplementation(() => {});
    loadWorkspaceYaml.mockClear();
    getRepoEntries.mockClear();
    setupSshKey.mockClear();
    ensureRepo.mockClear();
    analyzeRepo.mockClear();
    fs.existsSync.mockReset();
  });

  afterEach(() => {
    consoleSpy.mockRestore();
  });

  it('calls analyzeRepo for a repo with a local path that exists', async () => {
    loadWorkspaceYaml.mockReturnValue({ repos: [] });
    getRepoEntries.mockReturnValue([
      { id: 'my-repo', sshUrl: '', localPath: '/local/my-repo' },
    ]);
    fs.existsSync.mockReturnValue(true);
    analyzeRepo.mockResolvedValue(true);

    await runCycle(null);

    expect(analyzeRepo).toHaveBeenCalledWith('my-repo', '/local/my-repo', expect.any(String));
  });

  it('calls ensureRepo when local path does not exist but sshUrl is set', async () => {
    loadWorkspaceYaml.mockReturnValue({ repos: [] });
    getRepoEntries.mockReturnValue([
      { id: 'remote-repo', sshUrl: 'git@github.com:org/repo.git', localPath: null },
    ]);
    fs.existsSync.mockReturnValue(false);
    ensureRepo.mockReturnValue('/gitnexus-index/repos/remote-repo');
    analyzeRepo.mockResolvedValue(true);

    await runCycle('/tmp/id_rsa');

    expect(ensureRepo).toHaveBeenCalledWith(
      'remote-repo',
      'git@github.com:org/repo.git',
      expect.any(String),
      '/tmp/id_rsa',
    );
    expect(analyzeRepo).toHaveBeenCalled();
  });

  it('skips repo when no local path and no sshUrl', async () => {
    loadWorkspaceYaml.mockReturnValue({ repos: [] });
    getRepoEntries.mockReturnValue([
      { id: 'no-source-repo', sshUrl: '', localPath: null },
    ]);
    fs.existsSync.mockReturnValue(false);

    await runCycle(null);

    expect(analyzeRepo).not.toHaveBeenCalled();
    const logLines = consoleSpy.mock.calls.map((c) => JSON.parse(c[0]));
    const skipEvent = logLines.find((l) => l.event === 'gitnexus_repo_skip');
    expect(skipEvent).toBeDefined();
    expect(skipEvent.repoId).toBe('no-source-repo');
  });

  it('skips repo when ensureRepo returns null (clone failed)', async () => {
    loadWorkspaceYaml.mockReturnValue({ repos: [] });
    getRepoEntries.mockReturnValue([
      { id: 'bad-repo', sshUrl: 'git@github.com:org/bad.git', localPath: null },
    ]);
    fs.existsSync.mockReturnValue(false);
    ensureRepo.mockReturnValue(null);

    await runCycle(null);

    expect(analyzeRepo).not.toHaveBeenCalled();
  });

  it('handles multiple repos in one cycle', async () => {
    loadWorkspaceYaml.mockReturnValue({ repos: [] });
    getRepoEntries.mockReturnValue([
      { id: 'repo-a', sshUrl: '', localPath: '/local/a' },
      { id: 'repo-b', sshUrl: '', localPath: '/local/b' },
    ]);
    fs.existsSync.mockReturnValue(true);
    analyzeRepo.mockResolvedValue(true);

    await runCycle(null);

    expect(analyzeRepo).toHaveBeenCalledTimes(2);
  });

  it('propagates loadWorkspaceYaml errors to the caller', async () => {
    loadWorkspaceYaml.mockImplementation(() => { throw new Error('bad yaml'); });

    await expect(runCycle(null)).rejects.toThrow('bad yaml');
  });
});

