'use strict';

const { spawn } = require('child_process');
const { log } = require('./logger');

/**
 * Run `npx gitnexus@latest analyze <repoPath>` with HOME set to gitnexusDataPath.
 *
 * Emits structured log events:
 *   gitnexus_analyze_start  — before the process starts
 *   gitnexus_analyze_done   — on exit code 0
 *   gitnexus_analyze_failed — on non-zero exit or spawn error
 *
 * @param {string} repoId - Repo identifier for log context
 * @param {string} repoPath - Absolute path to the cloned repo
 * @param {string} [gitnexusDataPath='/gitnexus-data'] - HOME override so the index
 *   lands on the named Docker volume instead of the container ephemeral fs
 * @returns {Promise<boolean>} Resolves true on success, false on failure
 */
function analyzeRepo(repoId, repoPath, gitnexusDataPath = '/gitnexus-data') {
  return new Promise((resolve) => {
    log('gitnexus_analyze_start', { repoId, repoPath });

    const env = { ...process.env, HOME: gitnexusDataPath };
    const proc = spawn('npx', ['-y', 'gitnexus@latest', 'analyze', repoPath], {
      env,
      stdio: ['ignore', 'pipe', 'pipe'],
    });

    let stderr = '';
    proc.stdout.on('data', () => {}); // drain to prevent buffer back-pressure
    proc.stderr.on('data', (data) => { stderr += data.toString(); });

    proc.on('close', (code) => {
      if (code === 0) {
        log('gitnexus_analyze_done', { repoId, repoPath });
        resolve(true);
      } else {
        log('gitnexus_analyze_failed', {
          repoId,
          repoPath,
          exitCode: code,
          stderr: stderr.slice(0, 500),
        });
        resolve(false);
      }
    });

    proc.on('error', (err) => {
      log('gitnexus_analyze_failed', { repoId, repoPath, error: err.message });
      resolve(false);
    });
  });
}

module.exports = { analyzeRepo };
